class Solution {
public:
    int numberOfArrays(vector<int>& differences, int lower, int upper) {
        long long curr = 0, minVal = 0, maxVal = 0;
        for (int d : differences) {
            curr += d;
            minVal = min(minVal, curr);
            maxVal = max(maxVal, curr);
        }
        long long span = maxVal - minVal;
        long long count = (upper - lower) - span + 1;
        return count > 0 ? count : 0;
    }
};

class Solution {
    public int numberOfArrays(int[] differences, int lower, int upper) {
        long curr = 0, minVal = 0, maxVal = 0;
        for (int d : differences) {
            curr += d;
            minVal = Math.min(minVal, curr);
            maxVal = Math.max(maxVal, curr);
        }
        long span = maxVal - minVal;
        long count = (upper - lower) - span + 1;
        return count > 0 ? (int) count : 0;
    }
}

var numberOfArrays = function(differences, lower, upper) {
    let curr = 0, minVal = 0, maxVal = 0;
    for (const d of differences) {
        curr += d;
        minVal = Math.min(minVal, curr);
        maxVal = Math.max(maxVal, curr);
    }
    const span = maxVal - minVal;
    const count = (upper - lower) - span + 1;
    return count > 0 ? count : 0;
